\begin{aligned}
&\textbf{Equilibrium (plane‑stress)}: \qquad 
\nabla\!\cdot\!\Big[-p\,\mathbf I
+2\mu\,\mathbf e
+\lambda\big(\nabla\!\cdot\!\mathbf u\big)\mathbf I
+k_f\,(\mathbf n\otimes\mathbf n)\,
\big(\mathbf n\!\cdot\!\mathbf e\!\cdot\!\mathbf n\big)\Big]
=\mathbf 0, \\[4pt]
&\qquad\text{with }\;
\mathbf e=\tfrac12\big(\nabla\mathbf u+(\nabla\mathbf u)^{\!T}\big),\;
\mathbf n=(\cos\theta,\;\sin\theta), \\[6pt]
&\textbf{Fluid mass balance}: \qquad 
\frac{\partial}{\partial t}\big(\nabla\!\cdot\!\mathbf u\big)
-\nabla\!\cdot\!\Big[\kappa_0\big(1+\alpha\cos^{2}\theta\big)\,\nabla p\Big]=0,
\end{aligned}
}
\]

or, in explicit component form (using \(\varepsilon_{ij}=e_{ij}\) and 
\(\varepsilon_f=\mathbf n\!\cdot\!\mathbf e\!\cdot\!\mathbf n\)):

\[
\boxed{
\begin{aligned}
&\frac{\partial}{\partial x}\Big[-p+2\mu\varepsilon_{xx}
+\lambda(\varepsilon_{xx}+\varepsilon_{yy})
+k_f\cos^{2}\theta\,\varepsilon_f\Big]
+\frac{\partial}{\partial y}\Big[\mu(\varepsilon_{xy}+\varepsilon_{yx})
+k_f\cos\theta\sin\theta\,\varepsilon_f\Big]=0,\\[4pt]
&\frac{\partial}{\partial x}\Big[\mu(\varepsilon_{xy}+\varepsilon_{yx})
+k_f\cos\theta\sin\theta\,\varepsilon_f\Big]
+\frac{\partial}{\partial y}\Big[-p+2\mu\varepsilon_{yy}
+\lambda(\varepsilon_{xx}+\varepsilon_{yy})
+k_f\sin^{2}\theta\,\varepsilon_f\Big]=0,\\[4pt]
&\frac{\partial}{\partial t}(\varepsilon_{xx}+\varepsilon_{yy})
-\nabla\!\cdot\!\Big[\kappa_0\big(1+\alpha\cos^{2}\theta\big)\,\nabla p\Big]=0,\\[4pt]
&\varepsilon_f=\cos^{2}\theta\,\varepsilon_{xx}
+2\cos\theta\sin\theta\,\varepsilon_{xy}
+\sin^{2}\theta\,\varepsilon_{yy}.
\end{aligned}
}
\]

Here \(\mathbf u(x,y)\) is the in‑plane displacement, \(p(x,y)\) the interstitial fluid pressure, and the boundary condition on the anterior surface is \(p=\Delta P\) (with \(\Delta P=5\) mmHg) while the posterior surface is traction‑free \((\boldsymbol\sigma_s\!\cdot\!\mathbf n=0)\).

